        h, m = t.split(":")
        return int(h) * 60 + int(m)
    pts = []
    for s, e in meetings:
        pts.append((to_min(s), to_min(e)))
    pts.sort()
    total = 0
    cur_end = None
    for s, e in pts:
        if cur_end is None or s > cur_end:
            total += e - s
            cur_end = e
        elif e > cur_end:
            total += e - cur_end
            cur_end = e
    return total
