```python
def extent(data):
    if not data:
        return None
    if isinstance(data[0], list):
        inner = extent(data[0])
        if inner is None:
            return None
        lo, hi = inner
    else:
        lo, hi = data[0], data[0]
    for item in data[1:]:
        if isinstance(item, list):
            inner = extent(item)
            if inner is None:
                continue
            a, b = inner
        else:
            a, b = item, item
        lo = min(lo, a)
        hi = max(hi, b)
    return (lo, hi)
```

