def free_ranges(booked, days):
    free = []
    cur = 1
    for b in sorted(booked):
        if b > cur:
            free.append((cur, b - 1))
        cur = max(cur, b + 1)
    if cur <= days:
        free.append((cur, days))
    return free
```

