def longest_positive_product_run(changes):
    best = 0
    left = 0
    neg = 0
    for i, x in enumerate(changes):
        if x == 0:
            left = i + 1
            neg = 0
        elif neg % 2 == 0:
            best = max(best, i - left + 1)
        else:
            neg += 1
    return best
```

